def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find separator row and column
    sep_row = None
    sep_color = None
    for r in range(h):
        if all(grid[r][c] == grid[r][0] for c in range(w)):
            sep_row = r
            sep_color = grid[r][0]
            break

    sep_col = None
    for c in range(w):
        uniform = True
        for r in range(h):
            if grid[r][c] != grid[0][c]:
                uniform = False
                break
        if uniform:
            sep_col = c
            sep_color = grid[0][c]
            break

    # Find pattern quadrant
    quadrants = [
        (range(sep_row), range(sep_col)),           # TL
        (range(sep_row, h), range(sep_col)),        # BL
        (range(sep_row), range(sep_col, w)),        # TR
        (range(sep_row, h), range(sep_col, w))      # BR
    ]

    pattern_rows, pattern_cols = None, None
    for rows, cols in quadrants:
        non_sep = set()
        for r in rows:
            for c in cols:
                if grid[r][c] != sep_color:
                    non_sep.add(grid[r][c])
        if len(non_sep) >= 1:
            pattern_rows, pattern_cols = list(rows), list(cols)
            break

    # Count colors to find background (most frequent non-separator)
    from collections import Counter
    counts = Counter()
    for r in pattern_rows:
        for c in pattern_cols:
            if grid[r][c] != sep_color:
                counts[grid[r][c]] += 1

    if counts:
        bg_color = max(counts, key=counts.get)
        pattern_color = [c for c in counts if c != bg_color][0]
    else:
        bg_color = sep_color
        pattern_color = sep_color

    # Extract and map quadrant: bg -> pattern_color, pattern -> sep_color (from bg->sep then swap)
    # Actually: bg->sep, pattern->bg
    quh, qw = len(pattern_rows), len(pattern_cols)
    mapped = []
    for r in pattern_rows:
        row = []
        for c in pattern_cols:
            if grid[r][c] == bg_color:
                row.append(pattern_color)  # bg becomes pattern
            else:
                row.append(sep_color)      # pattern stays as pattern color in output
        mapped.append(row)

    # Mirror horizontally and vertically to create full symmetric output
    output = []
    for r in range(quh):
        half_row = mapped[r]
        full_row = half_row + half_row[::-1]
        output.append(full_row)
    output.extend(output[::-1])

    return output
